import { Injectable, signal } from '@angular/core';
import { DESIGNS, DesignInfo } from './designs.generated';

/** Swaps the lazily loaded theme bundle generated by scripts/angular-themes.mjs. */
@Injectable({ providedIn: 'root' })
export class ThemeService {
  public readonly designs = DESIGNS;
  public readonly design = signal<DesignInfo>(DESIGNS[0]);
  public readonly variant = signal('light');
  public readonly baseOnly = signal(false);

  constructor() {
    const params = new URLSearchParams(location.search);
    const design = DESIGNS.find((d) => d.slug === params.get('design'));
    if (design) this.design.set(design);
    if (params.get('variant') === 'dark') this.variant.set('dark');
    this.baseOnly.set(params.get('base') === '1');
    this.apply();
  }

  public update(changes: { slug?: string; variant?: string; baseOnly?: boolean }): void {
    if (changes.slug) this.design.set(DESIGNS.find((d) => d.slug === changes.slug) ?? DESIGNS[0]);
    if (changes.variant) this.variant.set(changes.variant);
    if (changes.baseOnly !== undefined) this.baseOnly.set(changes.baseOnly);
    if (!this.design().variants.includes(this.variant())) this.variant.set(this.design().variants[0]);
    this.apply();
  }

  private apply(): void {
    const d = this.design();
    const bundle = this.baseOnly() ? `base-${d.base}-${this.variant()}` : `design-${d.slug}-${this.variant()}`;
    let link = document.getElementById('ig-theme') as HTMLLinkElement | null;
    if (!link) {
      link = Object.assign(document.createElement('link'), { id: 'ig-theme', rel: 'stylesheet' });
      document.head.append(link);
    }
    link.href = `${bundle}.css`;
    document.documentElement.dataset['variant'] = this.variant();

    for (const href of d.fonts ?? []) {
      if (!document.querySelector(`link[href="${href}"]`)) {
        document.head.append(Object.assign(document.createElement('link'), { rel: 'stylesheet', href }));
      }
    }

    const url = new URL(location.href);
    url.searchParams.set('design', d.slug);
    url.searchParams.set('variant', this.variant());
    url.searchParams.set('base', this.baseOnly() ? '1' : '0');
    history.replaceState(null, '', url);
  }
}
